messages.content:
{
 "what_you_observe": [
  "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice.",
  "An envelope has arrived from Pittsburgh. Alma's daughter sent a receipt for a recorded interview. The line copied her reply: 'I know that voice. Play it again.'"
 ],
 "your_own_memories": [
  {
   "when": "last Tuesday afternoon",
   "witnessed": "Phil uses the paid ticket and rides the coach all the way to Pittsburgh.."
  },
  {
   "when": "last evening in Pittsburgh",
   "witnessed": "You reached your sister from the terminal payphone. She confirmed the van booking for Wednesday.",
   "your_words": "Hey, it's Phil. I'm in Pittsburgh now, just off the coach. Listen, about tomorrow—van's booked for the couch, right? I want to nail down the pickup time and make sure I know which hallway we're dragging it through. I'll be at your place by noon, tops."
  },
  {
   "when": "this morning",
   "witnessed": "After that evening in Pittsburgh you woke back in your hotel bed. The radio again announced Tuesday, February 2."
  },
  {
   "afternoon": "Phil rides the coach and steps off at Pittsburgh.",
   "evening": "Phil calls his sister in Pittsburgh. The van is still booked for Wednesday.",
   "what_you_said": "Hey. It's Dad. Rita told me to call. I'm in Pittsburgh, I'm at the station, I'm fine. I'm here for tomorrow. I'm really here. … You don't have to say anything. I just needed you to hear my voice tonight. Okay. Okay. I'll talk to you in the morning.",
   "your_last_intention": "Give Alma her father's voice tonight, in a room full of other people's noise, so that tomorrow when I'm in my sister's hallway with the couch and the sweat and the swearing, I am not a stranger to her. And so that when I wake up — if I wake up in this hotel bed again — I at least had one real hour where I was a person in a place, not a forecast.",
   "next_wake": "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice."
  },
  {
   "afternoon": "Phil records Alma's interview and leaves it at the patch.",
   "evening": "Phil waits at the empty Rialto booth.",
   "what_you_said": "(none)",
   "your_last_intention": "Be a body in a chair for three hours. Not a forecast. Not a loop. Not a man talking to a payphone to make himself real. Just sitting. Hands on the desk. Knees on the floor. The couch is Wednesday. The coach is tomorrow. Tonight I am allowed to be still in a room that is lit and open and does not need me to do anything in it. That is the whole act. That is enough.",
   "next_wake": "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice."
  },
  {
   "afternoon": "Phil changes the flat. The driver gets back on the road.",
   "evening": "Phil plays the piano at the ballroom.",
   "what_you_said": "Silence. One exhale through the nose when the last note fades. Nothing else. No name. No 'okay.' No 'good.' Just the breath out and the hands flat on the keys and the room lit and open and not needing him to explain why he's there.",
   "your_last_intention": "My hands just spent twenty minutes on a tire and they remember the wrench and the cold and the smell of rubber and they want to stop being a tool. The keys don't need me to be right. They don't need me to be a forecast or a phone call or a man in a booth waiting to be seen. I press them and the sound is there and then it isn't and that's the whole transaction. Eleven minutes. Then I wash my hands. Then I get on the bus. Then I'm in Pittsburgh. Then I'm in my sister's hallway and the couch is heavy and the hallway is narrow and I'm the one doing the lifting and the swearing and the sweat and she's watching and I'm not a stranger to her and I'm not a voice on a payphone and I'm not a body in a chair. I'm the guy moving the couch. That's the whole thing. That's all it is. Wednesday. The couch. My hands on the wood, not the keys. The hallway. The weight. The swearing. The sweat. She's there. I'm there. That's enough.",
   "next_wake": "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice."
  }
 ],
 "who_you_are_with": "your present location",
 "physical_choices": {
  "get_up": "Get up and choose what to do today.",
  "stay_in_bed": "Turn over and stay in bed.",
  "listen_again": "Stay still and listen for the second backfire."
 }
}
